static class Launcher{
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool created;using(var mutex=new Mutex(true,"Local\\LifeAC-Lighting-Host",out created)){
 if(args.Length==1&&args[0]=="--install"){if(!created){MessageBox.Show("Close LifeAC Lighting from its tray menu before installing.");return 1;}return Install();}
 if(!created){try{using(var p=new NamedPipeClientStream(".","LifeACLightingOpen",PipeDirection.Out)){p.Connect(1500);using(var w=new StreamWriter(p)){w.WriteLine("open");}}}catch{MessageBox.Show("LifeAC Lighting is already starting. Look for its tray icon.");}return 0;}
