 static int Install(){try{string source=AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\'),target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","LifeAC-Lighting","releases","0.6.1-"+DateTime.Now.ToString("yyyyMMddHHmmss"));if(source.Equals(target,StringComparison.OrdinalIgnoreCase)||target.StartsWith(source+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Install from an extracted folder outside the destination");Copy(source,target);
