 static void Copy(string source,string dest){Directory.CreateDirectory(dest);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(dest,Path.GetFileName(file)),false);foreach(string dir in Directory.GetDirectories(source)){if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;Copy(dir,Path.Combine(dest,Path.GetFileName(dir)));}}
}
